using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.RegularExpressions;
namespace PaoCaixa {
 public sealed class Store:IDisposable {
  public const string OwnerId="owner-biel",OwnerEmail="biel.bitencourt01@gmail.com";
  public readonly object Sync=new object(); public readonly string DirectoryPath,FilePath,Backups;
  readonly Sqlite sql; readonly RemoteControl remote; string sessionId;long sessionVersion; User dummy;
  static readonly string[] Tables={"products","sales","sessions","cash_moves","stock_moves"};
  public static string Resource(string name){using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream(name))using(var r=new StreamReader(s))return r.ReadToEnd();}
  public Store(string directory,RemoteControl remoteControl=null){remote=remoteControl;DirectoryPath=directory;FilePath=Path.Combine(directory,"padaria.sqlite");Backups=Path.Combine(directory,"backups");Directory.CreateDirectory(Backups);bool existing=File.Exists(FilePath);sql=new Sqlite(FilePath);
   try{
    bool firstNative=sql.Scalar("SELECT name FROM sqlite_master WHERE name='native_sales_at'")==null;
    if(existing&&(string)sql.Scalar(firstNative?"PRAGMA integrity_check":"PRAGMA quick_check")!="ok")throw new Exception("O banco precisa ser recuperado. O arquivo original foi preservado.");long version=Convert.ToInt64(sql.Scalar("PRAGMA user_version"));if(version>2)throw new Exception("Banco de uma versão mais nova. Instale a versão mais recente.");
    if(version==0){if(sql.Query("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'").Count!=0)throw new Exception("Banco desconhecido. O arquivo original foi preservado.");sql.Transaction(()=>{
      sql.Exec("CREATE TABLE metadata(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL,next_sale INTEGER NOT NULL,settings TEXT NOT NULL)");foreach(var t in Tables)sql.Exec("CREATE TABLE "+t+"(id TEXT PRIMARY KEY,position INTEGER NOT NULL,payload TEXT NOT NULL)");sql.Exec("CREATE TABLE draft(singleton INTEGER PRIMARY KEY CHECK(singleton=1),payload TEXT NOT NULL)");WriteState(D.Validate(J.Read<State>(Resource("seed.json"))));sql.Exec("PRAGMA user_version=1");
     });}
    sql.Exec("PRAGMA journal_mode=WAL");if(firstNative)D.Validate(LoadRaw());else if(sql.Scalar("SELECT revision FROM metadata WHERE singleton=1")==null)throw new Exception("Banco incompleto.");
    if(version<2){if(existing)Backup("antes-contas");sql.Transaction(()=>{
      sql.Exec("CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','operator','financial')),is_owner INTEGER NOT NULL DEFAULT 0 CHECK(is_owner IN(0,1)),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),salt TEXT NOT NULL,password_hash TEXT NOT NULL,credential_version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL)");
      sql.Exec("CREATE UNIQUE INDEX only_one_owner ON users(is_owner) WHERE is_owner=1");sql.Exec("CREATE TRIGGER protect_owner_delete BEFORE DELETE ON users WHEN OLD.is_owner=1 BEGIN SELECT RAISE(ABORT,'A conta proprietária não pode ser removida.'); END");
      sql.Exec("CREATE TRIGGER protect_owner_update BEFORE UPDATE ON users WHEN OLD.is_owner=1 AND(NEW.id<>OLD.id OR NEW.email<>OLD.email OR NEW.role<>'admin' OR NEW.is_owner<>1 OR NEW.active<>1) BEGIN SELECT RAISE(ABORT,'A conta proprietária não pode ser alterada ou bloqueada.'); END");
      sql.Exec("CREATE TABLE user_drafts(user_id TEXT PRIMARY KEY REFERENCES users(id),payload TEXT NOT NULL)");sql.Exec("CREATE TABLE login_attempts(singleton INTEGER PRIMARY KEY CHECK(singleton=1),failures INTEGER NOT NULL,blocked_until INTEGER NOT NULL)");sql.Exec("CREATE TABLE installation_control(singleton INTEGER PRIMARY KEY CHECK(singleton=1),blocked INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '',changed_at TEXT)");sql.Exec("INSERT INTO installation_control(singleton) VALUES(1)");sql.Exec("CREATE TABLE access_audit(id INTEGER PRIMARY KEY,at TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL)");sql.Exec("PRAGMA user_version=2");
     });}
    var bootstrap=J.Read<Dictionary<string,string>>(Resource("owner-bootstrap.json"));dummy=new User{salt=bootstrap["salt"],password_hash=bootstrap["password_hash"]};
    if(sql.Scalar("SELECT id FROM users WHERE is_owner=1")==null){sql.Transaction(()=>{
      sql.Exec("INSERT INTO users(id,email,name,role,is_owner,active,salt,password_hash,created_at) VALUES(?,?,?,'admin',1,1,?,?,?)",OwnerId,OwnerEmail,"Biel Carreon",dummy.salt,dummy.password_hash,D.Now());
      string raw=(string)sql.Scalar("SELECT payload FROM draft WHERE singleton=1")??J.Write(new Draft());sql.Exec("INSERT INTO user_drafts VALUES(?,?)",OwnerId,raw);sql.Exec("INSERT OR REPLACE INTO draft VALUES(1,?)",J.Write(new Draft()));var r=OpenRaw();if(r!=null&&string.IsNullOrEmpty(r.userId)){r.userId=OwnerId;Update("sessions",r.id,r);}
     });}
    var owner=UserRecord("SELECT * FROM users WHERE is_owner=1");if(owner==null||owner.id!=OwnerId||owner.email!=OwnerEmail||owner.role!="admin"||owner.active!=1)throw new Exception("Conta proprietária inválida. Recupere um backup.");
    if(existing&&firstNative)Backup("antes-versao-nativa");
    sql.Exec("CREATE INDEX IF NOT EXISTS native_sales_session ON sales(json_extract(payload,'$.sessionId'),json_extract(payload,'$.status'))");sql.Exec("CREATE INDEX IF NOT EXISTS native_sales_at ON sales(json_extract(payload,'$.at'))");sql.Exec("CREATE INDEX IF NOT EXISTS native_session_status ON sessions(json_extract(payload,'$.status'))");sql.Exec("CREATE INDEX IF NOT EXISTS native_cash_session ON cash_moves(json_extract(payload,'$.sessionId'))");sql.Exec("CREATE INDEX IF NOT EXISTS native_stock_product ON stock_moves(json_extract(payload,'$.productId'))");
   }catch{sql.Dispose();throw;}
  }
  static User MapUser(Dictionary<string,object> r){return new User{id=(string)r["id"],email=(string)r["email"],name=(string)r["name"],role=(string)r["role"],salt=(string)r["salt"],password_hash=(string)r["password_hash"],created_at=(string)r["created_at"],active=(long)r["active"],is_owner=(long)r["is_owner"],credential_version=(long)r["credential_version"]};}
  User UserRecord(string q,params object[] a){var rows=sql.Query(q,a);return rows.Count==0?null:MapUser(rows[0]);}
  public ControlState Control(){Current();return ControlRaw();}
  ControlState ControlRaw(){var r=sql.Query("SELECT * FROM installation_control WHERE singleton=1")[0];return new ControlState{blocked=(long)r["blocked"],reason=(string)r["reason"],changed_at=(string)r["changed_at"]};}
  public User Current(){if(remote!=null)remote.AssertAllowed();var u=sessionId==null?null:UserRecord("SELECT * FROM users WHERE id=?",sessionId);if(u==null||u.active!=1||u.credential_version!=sessionVersion){sessionId=null;throw new Exception("Entre com seu e-mail e senha para continuar.");}if(!u.Owner&&ControlRaw().blocked==1)throw new Exception("O acesso desta instalação foi suspenso. Entre em contato com o responsável.");return u;}
  public User Admin(){var u=Current();if(u.role!="admin")throw new Exception("Somente administradores podem realizar esta operação.");return u;}
  public User Owner(){var u=Current();if(!u.Owner)throw new Exception("Este painel é exclusivo da conta proprietária.");return u;}
  User Cashier(){var u=Current();if(u.role=="financial")throw new Exception("O perfil financeiro tem acesso de consulta e não pode operar o caixa.");return u;}
  User OwnRegister(){var u=Cashier();var r=OpenRaw();if(r==null)throw new Exception("Abra o caixa antes de vender.");if(u.role=="operator"&&r.userId!=u.id)throw new Exception("Você só pode operar seu próprio caixa aberto.");return u;}
  public User Login(string email,string password){if(remote!=null)remote.AssertAllowed();if(sessionId!=null)throw new Exception("Saia da conta atual antes de entrar em outra.");var rows=sql.Query("SELECT * FROM login_attempts WHERE singleton=1");long failures=rows.Count==0?0:(long)rows[0]["failures"],until=rows.Count==0?0:(long)rows[0]["blocked_until"],now=(long)(DateTime.UtcNow-new DateTime(1970,1,1)).TotalMilliseconds;if(until>now)throw new Exception("Muitas tentativas. Aguarde "+(int)Math.Ceiling((until-now)/1000.0)+" segundos.");
   var u=UserRecord("SELECT * FROM users WHERE email=?",(email??"").Trim().ToLowerInvariant());bool valid=Passwords.Verify(password,u??dummy);if(u==null||u.active!=1||!valid){failures++;until=failures>=5?now+Math.Min(600000,30000*(long)Math.Pow(2,Math.Min(5,failures-5))):0;sql.Exec("INSERT OR REPLACE INTO login_attempts VALUES(1,?,?)",failures,until);throw new Exception("E-mail ou senha inválidos, ou conta desativada.");}if(!u.Owner&&ControlRaw().blocked==1)throw new Exception("O acesso desta instalação foi suspenso. Entre em contato com o responsável.");sql.Exec("DELETE FROM login_attempts");sessionId=u.id;sessionVersion=u.credential_version;Audit("login","");return Current();
  }
  public void Logout(){sessionId=null;}
  void Audit(string action,string detail){var u=Current();sql.Exec("INSERT INTO access_audit(at,actor_id,action,detail) VALUES(?,?,?,?)",D.Now(),u.id,action,detail);}
  public List<User> Users(){Owner();return sql.Query("SELECT * FROM users ORDER BY is_owner DESC,created_at").Select(MapUser).Select(u=>{u.salt=null;u.password_hash=null;return u;}).ToList();}
  public List<Dictionary<string,object>> AuditList(){Owner();return sql.Query("SELECT at,action,detail FROM access_audit ORDER BY id DESC LIMIT 50");}
  static string Role(string r){if(!new[]{"admin","operator","financial"}.Contains(r))throw new Exception("Perfil inválido.");return r;}
  public void SaveUser(string id,string email,string name,string role,bool active,string password){Owner();name=D.Text(name,"o nome",60);Role(role);var old=string.IsNullOrEmpty(id)?null:UserRecord("SELECT * FROM users WHERE id=?",id);if(!string.IsNullOrEmpty(id)&&old==null)throw new Exception("Conta não encontrada.");if(old!=null&&old.Owner)throw new Exception("A conta proprietária é protegida.");if(old==null){email=(email??"").Trim().ToLowerInvariant();if(email.Length>254||!Regex.IsMatch(email,@"^[^\s@]+@[^\s@]+\.[^\s@]+$"))throw new Exception("Informe um e-mail válido.");if(sql.Scalar("SELECT id FROM users WHERE email=?",email)!=null)throw new Exception("Já existe uma conta com este e-mail.");}string salt=old==null?Passwords.Salt():old.salt,hash=old==null?null:old.password_hash;if(old==null||!string.IsNullOrEmpty(password)){Passwords.Validate(password);salt=Passwords.Salt();hash=Passwords.Hash(password,salt);}Owner();
   sql.Transaction(()=>{if(old==null)sql.Exec("INSERT INTO users(id,email,name,role,active,salt,password_hash,created_at) VALUES(?,?,?,?,?,?,?,?)",D.Id(),email,name,role,active?1:0,salt,hash,D.Now());else sql.Exec("UPDATE users SET name=?,role=?,active=?,salt=?,password_hash=?,credential_version=credential_version+1 WHERE id=?",name,role,active?1:0,salt,hash,id);Audit(old==null?"account.create":"account.update",old==null?email:old.email);});
  }
  public void ChangePassword(string current,string next){var u=Current();if(!Passwords.Verify(current,u))throw new Exception("A senha atual está incorreta.");Passwords.Validate(next);var salt=Passwords.Salt();var hash=Passwords.Hash(next,salt);Current();sql.Transaction(()=>{sql.Exec("UPDATE users SET salt=?,password_hash=?,credential_version=credential_version+1 WHERE id=?",salt,hash,u.id);sessionVersion++;Audit("password.change","");});}
  public void Block(bool blocked,string reason){Owner();if((reason??"").Length>200)throw new Exception("Motivo deve ter até 200 caracteres.");sql.Transaction(()=>{sql.Exec("UPDATE installation_control SET blocked=?,reason=?,changed_at=? WHERE singleton=1",blocked?1:0,(reason??"").Trim(),D.Now());Audit(blocked?"installation.block":"installation.unblock",reason??"");});}
  List<T> All<T>(string table){return sql.Query("SELECT payload FROM "+table+" ORDER BY position").Select(r=>J.Read<T>((string)r["payload"])).ToList();}
  public List<Product> Products(){var u=Current();var p=All<Product>("products");if(u.role=="operator")foreach(var x in p)x.cost=0;return p;}
  Product ProductRaw(string id){var s=(string)sql.Scalar("SELECT payload FROM products WHERE id=?",id);if(s==null)throw new Exception("Produto não encontrado.");return J.Read<Product>(s);}
  Register OpenRaw(){var s=(string)sql.Scalar("SELECT payload FROM sessions WHERE json_extract(payload,'$.status')='open' LIMIT 1");return s==null?null:J.Read<Register>(s);}
  public Register Open(){var u=Current();var r=OpenRaw();return u.role=="operator"&&r!=null&&r.userId!=u.id?null:r;}
  public bool Occupied(){var u=Current();var r=OpenRaw();return r!=null&&u.role=="operator"&&r.userId!=u.id;}
  public long NextNumber(){Current();return Convert.ToInt64(sql.Scalar("SELECT next_sale FROM metadata WHERE singleton=1"));}
  public Settings Shop(){Current();return J.Read<Settings>((string)sql.Scalar("SELECT settings FROM metadata WHERE singleton=1"));}
  public long Revision(){return Convert.ToInt64(sql.Scalar("SELECT revision FROM metadata WHERE singleton=1"));}
  void Mutation(Action a){sql.Transaction(()=>{Current();a();sql.Exec("UPDATE metadata SET revision=revision+1 WHERE singleton=1");});}
  void Update(string table,string id,object payload){sql.Exec("UPDATE "+table+" SET payload=? WHERE id=?",J.Write(payload),id);}
  void Insert(string table,string id,object payload){sql.Exec("INSERT INTO "+table+" VALUES(?,COALESCE((SELECT MIN(position)-1 FROM "+table+"),0),?)",id,J.Write(payload));}
  public void OpenCash(long opening){var u=Cashier();D.Int(opening,"Fundo de troco");Mutation(()=>{if(OpenRaw()!=null)throw new Exception("Já existe um caixa aberto.");var r=new Register{id=D.Id(),openedAt=D.Now(),operatorName=u.name,userId=u.id,opening=opening,status="open"};Insert("sessions",r.id,r);});}
  public Totals SessionTotals(string id){var u=Current();var raw=(string)sql.Scalar("SELECT payload FROM sessions WHERE id=?",id);if(raw==null)throw new Exception("Caixa não encontrado.");var r=J.Read<Register>(raw);if(u.role=="operator"&&(r.status!="open"||r.userId!=u.id))throw new Exception("Você só pode consultar o seu caixa atualmente aberto.");return TotalsRaw(r);}
  Totals TotalsRaw(Register r){
   var t=new Totals{drawer=r.opening};
   var a=sql.Query("SELECT COUNT(*) AS count,COALESCE(SUM(json_extract(payload,'$.total')),0) AS revenue FROM sales WHERE json_extract(payload,'$.sessionId')=? AND json_extract(payload,'$.status')='paid'",r.id)[0];t.sales=(int)(long)a["count"];t.revenue=(long)a["revenue"];
   foreach(var p in sql.Query("SELECT json_extract(p.value,'$.method') AS method,SUM(json_extract(p.value,'$.amount')) AS amount FROM sales AS s,json_each(s.payload,'$.payments') AS p WHERE json_extract(s.payload,'$.sessionId')=? AND json_extract(s.payload,'$.status')='paid' GROUP BY method",r.id))t.payments[(string)p["method"]]=(long)p["amount"];
   foreach(var m in sql.Query("SELECT json_extract(payload,'$.type') AS kind,SUM(json_extract(payload,'$.amount')) AS amount FROM cash_moves WHERE json_extract(payload,'$.sessionId')=? GROUP BY kind",r.id)){if((string)m["kind"]=="supply")t.supplied=(long)m["amount"];else t.withdrawn=(long)m["amount"];}t.drawer+=t.payments["dinheiro"]+t.supplied-t.withdrawn;return t;
  }
  List<CashMove> CashRaw(string id){return sql.Query("SELECT payload FROM cash_moves WHERE json_extract(payload,'$.sessionId')=? ORDER BY position",id).Select(x=>J.Read<CashMove>((string)x["payload"])).ToList();}
  public List<CashMove> CashMoves(string id,int offset=0){SessionTotals(id);return sql.Query("SELECT payload FROM cash_moves WHERE json_extract(payload,'$.sessionId')=? ORDER BY position LIMIT 101 OFFSET ?",id,offset).Select(x=>J.Read<CashMove>((string)x["payload"])).ToList();}
  public List<Register> Registers(int offset=0){var u=Current();if(u.role=="operator"){var r=Open();return r==null?new List<Register>():new List<Register>{r};}return sql.Query("SELECT payload FROM sessions ORDER BY position LIMIT 101 OFFSET ?",offset).Select(x=>J.Read<Register>((string)x["payload"])).ToList();}
  public void MoveCash(string kind,long amount,string reason){OwnRegister();if(kind!="supply"&&kind!="withdrawal")throw new Exception("Movimentação inválida.");D.Int(amount,"Valor",1);reason=D.Text(reason,"o motivo");Mutation(()=>{OwnRegister();var r=OpenRaw();if(kind=="withdrawal"&&amount>TotalsRaw(r).drawer)throw new Exception("A sangria supera o dinheiro disponível no caixa.");var m=new CashMove{id=D.Id(),sessionId=r.id,at=D.Now(),type=kind,amount=amount,reason=reason};Insert("cash_moves",m.id,m);});}
  public void CloseCash(Dictionary<string,long> counted){OwnRegister();foreach(var m in D.Methods){if(!counted.ContainsKey(m))throw new Exception("Contagem inválida.");D.Int(counted[m],"Contagem");}Mutation(()=>{OwnRegister();var r=OpenRaw();var t=TotalsRaw(r);r.expected=t.payments;r.expected["dinheiro"]=t.drawer;r.counted=counted;r.difference=counted["dinheiro"]-t.drawer;r.closedAt=D.Now();r.status="closed";Update("sessions",r.id,r);});}
  public Draft GetDraft(){var u=Current();if(u.role=="financial")return new Draft();var raw=(string)sql.Scalar("SELECT payload FROM user_drafts WHERE user_id=?",u.id);return raw==null?new Draft():J.Read<Draft>(raw);}
  public void SetDraft(Draft d){WriteDraft(Cashier().id,d);}
  void WriteDraft(string userId,Draft d){if(d==null||d.cart==null||d.cart.Count>10000||d.discount==null||d.discount.Length>50||d.note==null||d.note.Length>200)throw new Exception("Venda em andamento inválida.");var seen=new HashSet<string>();foreach(var l in d.cart){if(string.IsNullOrEmpty(l.productId)||!seen.Add(l.productId)||l.quantity<=0||l.quantity>1000000000)throw new Exception("Item inválido.");}sql.Exec("INSERT INTO user_drafts VALUES(?,?) ON CONFLICT(user_id) DO UPDATE SET payload=excluded.payload",userId,J.Write(d));}
  internal void PreserveDraftOnRemoteLock(Draft d){
   if(remote==null||!remote.Denied)throw new Exception("Preservação restrita à suspensão remota.");
   var u=sessionId==null?null:UserRecord("SELECT * FROM users WHERE id=?",sessionId);
   if(u==null||u.active!=1||u.credential_version!=sessionVersion||u.role=="financial")throw new Exception("Não há pedido de operador autenticado para preservar.");
   WriteDraft(u.id,d); // Only saves the current private draft, never a sale or cash movement.
  }
  public bool HasDrafts(){return sql.Query("SELECT payload FROM user_drafts").Any(x=>J.Read<Draft>((string)x["payload"]).cart.Count>0);}
  public Sale Finish(List<Line> lines,long discount,List<Payment> payments,long received,string note){var u=OwnRegister();note=note??"";if(note.Length>200)throw new Exception("Observação deve ter até 200 caracteres.");Sale result=null;Mutation(()=>{OwnRegister();var r=OpenRaw();if(lines.Count==0)throw new Exception("Adicione um produto à venda.");var products=lines.Select(l=>ProductRaw(l.productId)).ToList();var c=D.Calculate(products,lines,discount);if(c.total<=0)throw new Exception("A venda deve ter um total maior que zero.");var methods=new HashSet<string>();foreach(var p in payments){if(!D.Methods.Contains(p.method)||!methods.Add(p.method))throw new Exception("Forma de pagamento inválida ou repetida.");D.Int(p.amount,"Pagamento",1);}if(payments.Sum(p=>p.amount)!=c.total)throw new Exception("A soma dos pagamentos deve ser igual ao total.");D.Int(received,"Dinheiro recebido");long cash=payments.Where(p=>p.method=="dinheiro").Sum(p=>p.amount);if(received<cash)throw new Exception("Dinheiro recebido insuficiente.");if(cash==0&&received!=0)throw new Exception("Dinheiro recebido requer pagamento em dinheiro.");
    result=new Sale{id=D.Id(),sessionId=r.id,at=D.Now(),number=Convert.ToInt64(sql.Scalar("SELECT next_sale FROM metadata WHERE singleton=1")),operatorName=u.name,userId=u.id,items=c.items,subtotal=c.subtotal,discount=discount,total=c.total,payments=payments,cashReceived=received,change=received-cash,note=note.Trim(),status="paid"};Insert("sales",result.id,result);foreach(var i in c.items){var p=products.Find(x=>x.id==i.productId);p.stock-=i.quantity;Update("products",p.id,p);var m=new StockMove{id=D.Id(),productId=p.id,at=result.at,quantity=-i.quantity,reason="Venda #"+result.number,saleId=result.id};Insert("stock_moves",m.id,m);}sql.Exec("UPDATE metadata SET next_sale=next_sale+1 WHERE singleton=1");sql.Exec("DELETE FROM user_drafts WHERE user_id=?",u.id);
   });return result;}
  public void Cancel(string id,string reason){var u=OwnRegister();reason=D.Text(reason,"o motivo do cancelamento");Mutation(()=>{OwnRegister();var raw=(string)sql.Scalar("SELECT payload FROM sales WHERE id=?",id);var v=raw==null?null:J.Read<Sale>(raw);var r=OpenRaw();if(v==null||v.status!="paid")throw new Exception("Venda inexistente ou já cancelada.");if(v.sessionId!=r.id)throw new Exception("Só é possível cancelar vendas do caixa atualmente aberto.");if(u.role=="operator"&&v.userId!=u.id)throw new Exception("Você só pode cancelar suas próprias vendas.");if(TotalsRaw(r).drawer<v.payments.Where(p=>p.method=="dinheiro").Sum(p=>p.amount))throw new Exception("Dinheiro insuficiente para devolver esta venda. Registre um suprimento.");v.status="cancelled";v.cancelledAt=D.Now();v.cancelReason=reason;Update("sales",id,v);foreach(var i in v.items){var p=ProductRaw(i.productId);p.stock+=i.quantity;D.Int(p.stock,"Estoque");Update("products",p.id,p);var m=new StockMove{id=D.Id(),productId=p.id,at=v.cancelledAt,quantity=i.quantity,reason="Cancelamento #"+v.number,saleId=v.id};Insert("stock_moves",m.id,m);}});}
  public List<Sale> Sales(DateTime start,DateTime end,int offset=0,int limit=101){var u=Current();string where="json_extract(payload,'$.at')>=? AND json_extract(payload,'$.at')<?";var args=new List<object>{start.ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ss.fffZ"),end.ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ss.fffZ")};if(u.role=="operator"){var r=Open();if(r==null)return new List<Sale>();where+=" AND json_extract(payload,'$.sessionId')=?";args.Add(r.id);}args.Add(limit);args.Add(offset);var rows=sql.Query("SELECT payload FROM sales WHERE "+where+" ORDER BY position LIMIT ? OFFSET ?",args.ToArray()).Select(x=>J.Read<Sale>((string)x["payload"])).ToList();if(u.role=="operator")foreach(var v in rows)foreach(var i in v.items)i.cost=0;return rows;}
  public IEnumerable<Sale> Report(DateTime start,DateTime end){ // Stream batches; callers aggregate, never keep the full history on the screen.
   int offset=0;while(true){var rows=Sales(start,end,offset,500);foreach(var v in rows)yield return v;if(rows.Count<500)yield break;offset+=500;}
  }
  public void SaveProduct(Product p){Admin();p.name=D.Text(p.name,"o nome",100);p.code=D.Text(p.code,"o código",60);p.category=D.Text(p.category,"a categoria",60);if(p.unit!="un"&&p.unit!="kg")throw new Exception("Unidade inválida.");D.Int(p.price,"Preço",1);D.Int(p.cost,"Custo");D.Int(p.minStock,"Estoque mínimo");Mutation(()=>{var all=All<Product>("products");var old=all.Find(x=>x.id==p.id);if(all.Any(x=>string.Equals(x.code,p.code,StringComparison.OrdinalIgnoreCase)&&x.id!=p.id))throw new Exception("Já existe um produto com esse código.");if(old!=null&&old.unit!=p.unit)throw new Exception("A unidade não pode ser alterada. Crie outro produto.");p.stock=old==null?p.stock:old.stock;D.Int(p.stock,"Estoque");if(p.unit=="un"&&(p.stock%1000!=0||p.minStock%1000!=0))throw new Exception("Estoque por unidade deve ser inteiro.");p.icon=p.icon??"bread";if(old==null){p.id=D.Id();Insert("products",p.id,p);if(p.stock!=0){var m=new StockMove{id=D.Id(),productId=p.id,at=D.Now(),quantity=p.stock,reason="Estoque inicial"};Insert("stock_moves",m.id,m);}}else Update("products",p.id,p);});}
  // Adiciona somente produtos demonstrativos ausentes; não altera preços,
  // estoques ou códigos de produtos já cadastrados pelo estabelecimento.
  public int ImportExampleProducts(){
   Admin();
   var samples=J.Read<List<Product>>(Resource("catalog-extras.json"));
   int added=0;
   Mutation(()=>{
    var existing=All<Product>("products");
    var codes=new HashSet<string>(existing.Select(x=>x.code),StringComparer.OrdinalIgnoreCase);
    var names=new HashSet<string>(existing.Select(x=>x.name),StringComparer.CurrentCultureIgnoreCase);
    foreach(var template in samples){
     if(codes.Contains(template.code)||names.Contains(template.name))continue;
     var p=new Product{id=D.Id(),name=template.name,code=template.code,category=template.category,
      unit="un",price=template.price,cost=0,stock=0,minStock=0,active=true,
      icon=template.icon,photoKey=template.photoKey};
     Insert("products",p.id,p);
     codes.Add(p.code);names.Add(p.name);added++;
    }
   });
   return added;
  }
  public void AdjustStock(string id,long q,string reason){Admin();if(q==0||Math.Abs(q)>1000000000)throw new Exception("Informe uma quantidade válida.");reason=D.Text(reason,"o motivo");Mutation(()=>{var p=ProductRaw(id);if(p.unit=="un"&&q%1000!=0)throw new Exception("Quantidade por unidade deve ser inteira.");p.stock+=q;D.Int(p.stock,"Estoque");Update("products",id,p);var m=new StockMove{id=D.Id(),productId=id,at=D.Now(),quantity=q,reason=reason};Insert("stock_moves",m.id,m);});}
  public List<StockMove> StockHistory(string id,int offset=0){Admin();return sql.Query("SELECT payload FROM stock_moves WHERE json_extract(payload,'$.productId')=? ORDER BY position LIMIT 101 OFFSET ?",id,offset).Select(x=>J.Read<StockMove>((string)x["payload"])).ToList();}
  public void SaveSettings(Settings s){Admin();s.name=D.Text(s.name,"o nome da padaria",100);s.@operator=D.Text(s.@operator,"o operador",60);if(s.footer==null||s.footer.Length>200)throw new Exception("Rodapé inválido.");Mutation(()=>sql.Exec("UPDATE metadata SET settings=? WHERE singleton=1",J.Write(s)));}
  State LoadRaw(){var m=sql.Query("SELECT * FROM metadata WHERE singleton=1");if(m.Count==0)throw new Exception("Banco incompleto. Restaure um backup.");return new State{revision=(long)m[0]["revision"],nextSale=(long)m[0]["next_sale"],settings=J.Read<Settings>((string)m[0]["settings"]),products=All<Product>("products"),sales=All<Sale>("sales"),sessions=All<Register>("sessions"),cashMoves=All<CashMove>("cash_moves"),stockMoves=All<StockMove>("stock_moves")};}
  public State Export(){Admin();return LoadRaw();}
  void WriteState(State s){sql.Exec("INSERT OR REPLACE INTO metadata VALUES(1,?,?,?)",s.revision,s.nextSale,J.Write(s.settings));foreach(var t in Tables)sql.Exec("DELETE FROM "+t);WriteRows("products",s.products.Select(p=>new KeyValuePair<string,object>(p.id,p)));WriteRows("sales",s.sales.Select(p=>new KeyValuePair<string,object>(p.id,p)));WriteRows("sessions",s.sessions.Select(p=>new KeyValuePair<string,object>(p.id,p)));WriteRows("cash_moves",s.cashMoves.Select(p=>new KeyValuePair<string,object>(p.id,p)));WriteRows("stock_moves",s.stockMoves.Select(p=>new KeyValuePair<string,object>(p.id,p)));}
  void WriteRows(string table,IEnumerable<KeyValuePair<string,object>> rows){long i=0;foreach(var r in rows)sql.Exec("INSERT INTO "+table+" VALUES(?,?,?)",r.Key,i++,J.Write(r.Value));}
  public void Restore(State incoming,long expected){var u=Admin();D.Validate(incoming);if(Revision()!=expected)throw new Exception("Os dados mudaram. Confira e tente novamente.");Backup("antes-restauracao");sql.Transaction(()=>{if(Revision()!=expected)throw new Exception("Os dados mudaram.");incoming.revision=expected+1;foreach(var r in incoming.sessions)r.userId=r.status=="open"?u.id:null;foreach(var v in incoming.sales)v.userId=null;WriteState(incoming);sql.Exec("DELETE FROM user_drafts");sql.Exec("DELETE FROM draft");Audit("restore","");});}
  public string Backup(string reason="manual"){if(!Regex.IsMatch(reason,"^[a-z-]+$"))throw new Exception("Nome inválido.");string path=Path.Combine(Backups,DateTime.UtcNow.ToString("yyyy-MM-ddTHH-mm-ss-fff")+"-"+reason+"-"+D.Id().Substring(0,8)+".sqlite");sql.Exec("VACUUM INTO ?",path);return path;}
  public void DailyBackup(){string day=DateTime.UtcNow.ToString("yyyy-MM-dd");if(!Directory.GetFiles(Backups,day+"*-diario-*.sqlite").Any())Backup("diario");foreach(var p in Directory.GetFiles(Backups,"*-diario-*.sqlite").OrderByDescending(x=>x).Skip(30))File.Delete(p);}
  string UpdateBlockReason(){if(OpenRaw()!=null)return "Feche e confira o caixa antes de instalar a atualização.";if(HasDrafts())return "Conclua ou limpe todas as vendas em andamento antes de atualizar.";return null;}
  public string PrepareInstall(){Admin();string reason=UpdateBlockReason();if(reason!=null)throw new Exception(reason);return Backup("antes-atualizacao");}
  internal string StartupUpdateBlockReason(){return UpdateBlockReason();}
  internal string PrepareStartupInstall(){if(sessionId!=null)throw new Exception("A atualização automática só instala antes de entrar na conta.");string reason=UpdateBlockReason();if(reason!=null)throw new Exception(reason);return Backup("antes-atualizacao");}
  public void Dispose(){sql.Dispose();}
 }
